    "hero_btn_chronicle": "पवित्र इतिहास वाचा",
    "hero_btn_plan": "दर्शन वेळ व ई-पास",
    "hero_main_desc_1": "गुजरात राज्यातील डांग जिल्ह्यातील आहवा तालुक्यातील बिलमल येथील तुलसीगड या पवित्र ठिकाणी, आपले आदरणीय गुरु स्वामी अनेकरूपी महाराज यांच्या मार्गदर्शनाखाली भगवान शिव अधनारेश्वराची स्थापना करण्यात आली आहे. पुराणांनुसार, हा भाग त्याकाळी 'दंडकारण्य' क्षेत्र म्हणून ओळखला जात असे. येथे मुख्यत्वे नागदेवता आणि वाघोबा (वाघदेव) यांच्या मूर्तींचीही स्थापना केलेली आहे. त्यासोबतच येथे राधा-कृष्ण, विठ्ठल-रुक्मिणी, राम-लक्ष्मण-जानकी, हनुमान, पंचमुखी हनुमान, खंडेराव महाराज आणि भगवान गणेश यांच्या मूर्तीही प्रस्थापित आहेत. भारतातील एकमेव 'शिव अधनारेश्वर नाग ज्योतिर्लिंग धाम' आपल्याला फक्त तुलसीगड, बिलमल येथेच पाहायला मिळते.",
    "hero_main_desc_2": "या पवित्र धामात आल्यावर आपल्याला मंदिर आणि स्वामीजींच्या सान्निध्याने दैवी शक्तीची प्रचिती येते. तसेच, येथे आपल्याला इतर अनेक भाविकांच्या श्रद्धापूर्ण आणि दिव्य अनुभवांचे दर्शन घडते.",
    "hero_presence_tag": "सह्याद्रीच्या डोंगररांगांमध्ये निसर्गरूप शिवाचे साक्षात दर्शन",
    "hero_subtitle": "श्री शिव अर्धनरेश्वर नाग ज्योतिर्लिंग धाम — घनदाट जंगलातील पाषाण गुहा गर्भगृह, अखंड वैदिक नामघोष आणि पूज्य स्वामीजींची ४० वर्षांची मौन निसर्ग तपस्या.",
    "hero_threshold_text": "जंगल जसे प्रवेश करते, तसेच श्रद्धेने प्रवेश करा.",
    "hero_title": "जिथे अरण्यच प्रार्थना बनते.",
