    "mandir_cave_desc": "नैसर्गिक पाषाण गुहेत स्वयंभू नाग शिवलिंगाचे अधिष्ठान असून, अखंड वैदिक नामघोष व शांततेत दर्शन घडते.",
    "mandir_cave_title": "स्वयंभू पाषाण गुहा गर्भगृह",
    "mandir_discovery_desc": "१९८० च्या दशकात परमपूज्य संत स्वामी अनेकरूपीजी महाराजांनी गहन जंगलातील या स्वयंभू स्थानाचा साक्षात्कार घडवून अखंड धूणी व उपासनेची स्थापना केली.",
    "mandir_discovery_title": "पावन पुनरुत्थान इतिहास",
    "mandir_info_desc": "सह्याद्रीच्या कुशीत तुलसीगड टेकडीवर घनदाट डांग अरण्यात स्वयंभू अर्धनरेश्वर नाग ज्योतिर्लिंग प्रकट झाले आहे. पाषाण गुहेतून अखंड वाहणारा नैसर्गिक अमृत पाषाण झरा आणि शिव-शक्तीचे अद्वैत स्वरूप येथे भाविकांना अलौकिक शांती प्रदान करते.",
    "mandir_info_title": "श्री धाम व गुहा गर्भगृह परिचय",
    "mandir_parichay_ancient": "पुराणांनुसार हा भाग 'दंडकारण्य' क्षेत्र म्हणून ओळखला जात असे. येथे जप, तप आणि अनुष्ठान केल्याने विशेष पुण्यफलाची प्राप्ती होते.",
    "mandir_parichay_divine": "तुलसीगड परिसरात नागदेवतांचा दिव्य वावर असून, आध्यात्मिक दृष्ट्या नशीबवान भाविकांना त्यांचे दर्शन घडल्याच्या अनेक प्रचिती आहेत.",
    "mandir_parichay_establishment": "गुजरात राज्यातील डांग जिल्ह्यातील आहवा तालुक्यातील तुलसीगड या पवित्र ठिकाणी, आपले आदरणीय गुरु स्वामी अनेकरूपी महाराज यांच्या मार्गदर्शनाखाली भगवान शिव अधनारेश्वराची स्थापना करण्यात आली आहे.",
    "mandir_parichay_heading": "तुलसीगड: दिव्य शक्तीचे पावन धाम",
    "mandir_parichay_historical": "तुलसीगड शेजारील बिल्मल हे गाव पूर्वी 'बिल्व' (बेल) पत्राच्या वृक्षांच्या घनदाट जंगलाने व्यापलेले होते. काळाच्या ओघात वृक्षतोडीमुळे हे जंगल कमी झाले असले, तरी आजही येथे भगवान शिव आणि माता शक्तीच्या दिव्य अस्तित्वाची प्रचिती येते.",
    "mathadhipati_title": "मठाधीपती प.पू. संत स्वामी अनेकरूपीजी महाराज",
    "nag_dwar_sub": "अरण्यात ज्याप्रमाणे पावन भावाने प्रवेश करतो, तसाच श्रद्धेने या पवित्र धामात प्रवेश करा.",
    "nag_dwar_title": "नाग द्वार · पवित्र अरण्य प्रवेश",
    "nav_contact": "मार्गदर्शन व संपर्क",
    "nav_darshan": "दर्शन",
    "nav_events": "उत्सव",
