    "nav_yatra": "यात्रा व संपर्क",
    "news_placeholder_desc": "मंदिर ट्रस्टच्या अधिकृत सूचना, यात्रा मार्गदर्शक आणि धर्मसभेचे परिपत्रक येथे अद्ययावत केले जातात. तत्काळ वार्तांसाठी अधिकृत चॅनेल्स फॉलो करा.",
    "news_placeholder_title": "आगामी उत्सव व कार्यक्रम सूचना",
    "news_section_tag": "अधिकृत सूचना व वार्ता",
    "news_section_title": "मंदिर वार्ता व सूचना फलक",
    "niyam_1": "१. पवित्रता आणि स्वच्छता: मंदिरात प्रवेश करण्यापूर्वी स्नान करून शरीर आणि मन शुद्ध ठेवावे. मंदिर परिसरात थुंकणे किंवा कचरा करणे निषिद्ध आहे.",
    "niyam_10": "१०. मंदिर परिसरात प्लास्टिक पिशव्या आणि प्लास्टिक वस्तू वापरण्यास सक्त मनाई आहे. परिसर स्वच्छ ठेवा. कचरा केवळ कचराकुंडीतच टाकावा.",
    "niyam_11": "११. मंदिर परिसरात जंगली प्राणी असू शकतात, त्यामुळे एकटे फिरू नका आणि त्यांना त्रास देऊ नका. जंगली प्राण्यांना कोणतेही अन्न किंवा पदार्थ खाऊ घालू नका, हे धोकादायक ठरू शकते. जंगली प्राण्यांच्या वावरामुळे सूर्यास्तानंतर परिसरात फिरणे टाळावे.",
    "niyam_2": "२. पादुका/जोडे: मंदिरात प्रवेश करण्यापूर्वी आपली पादत्राणे (जोडे-चप्पल) बाहेरील नियुक्त ठिकाणीच उतरवावीत.",
    "niyam_3": "३. वेशभूषा (Dress Code): भारतीय संस्कृतीला साजेसे आणि मर्यादित वस्त्र परिधान करावे. तोकडे किंवा अशोभनीय कपडे घालून मंदिरात प्रवेश करू नये.",
    "niyam_4": "४. शांतता आणि शिस्त: मंदिर परिसरात मौन पाळावे. ओरडणे, मोठ्याने बोलणे किंवा धावणे टाळावे. मोबाईल फोन बंद ठेवावा किंवा 'सायलंट मोड'वर ठेवावा.",
    "niyam_5": "५. गर्भगृह मर्यादा: गर्भगृहातील मूर्तींना स्पर्श करू नये. प्रदक्षिणा नेहमी घड्याळाच्या काट्याच्या दिशेने (Clockwise) घालावी.",
    "niyam_6": "६. नशापान निषिद्ध: मंदिर परिसरात दारू, गुटखा, सिगारेट, तंबाखू किंवा कोणत्याही अमली पदार्थाचे सेवन करणे सक्त मनाई आहे.",
    "niyam_7": "७. छायाचित्रण (Photography): जर परवानगी नसेल, तर गाभाऱ्यात किंवा मूर्तीचे फोटो काढू नयेत आणि व्हिडिओ बनवू नये.",
    "niyam_8": "८. दान आणि दक्षिणा: दान केवळ दानपेटीतच टाकावे. मंदिराच्या पावित्र्याचा मान राखून सेवा करावी.",
    "niyam_9": "९. सुतक लागलेल्या काळामध्ये (साधारणपणे १० ते १३ दिवस) सुतकात घराबाहेर कोणाकडेही जेवू नये आणि आपल्या घरचे अन्न कोणाला देऊ नये. श्राद्धाच्या दिवशी आणि दशक्रियेपर्यंत अन्नाचे पावित्र्य महत्त्वाचे असते: श्राद्धाच्या दिवशी दुसऱ्याच्या घरचे अन्न घेऊ नये (पराअन्न वर्जन). दशक्रिया विधी (१० वा दिवस) आणि सांपिंडीकरण (१२ वा किंवा १३ वा दिवस) झाल्यानंतर शुद्धीकरण विधी केला जातो. त्यानंतरच घरामध्ये देवाची पूजा आणि सर्व प्रकारचे अन्न शिजवणे सुरू होते.",
    "niyam_heading": "मंदिर नियमावली",
    "niyamavali_tag": "नाग रक्षा कवच · पवित्र अरण्य शिस्त",
