    "official_donation_safety_notice": "⚠ अधिकृत सूचना: हे संकेतस्थळ (sdp-2-0.vercel.app) हेच श्री शिव अर्धनरेश्वरी नाग ज्योतिर्लिंग धाम, बिल्मल यांच्या देणगीसाठीचे एकमेव अधिकृत ऑनलाइन माध्यम आहे. कृपया इतर कोणत्याही संकेतस्थळ, अॅप किंवा व्यक्तीमार्फत देणगी पाठवू नये. पडताळणीसाठी थेट मंदिराशी संपर्क साधावा.",
