    "official_youtube_label": "अधिकृत YouTube चॅनेल",
    "offline_card_desc": "डांग अरण्यात काही ठिकाणी मोबाईल नेटवर्क नसते, म्हणून हा मार्गदर्शक व संपर्क कार्ड आधीच जतन करा.",
    "offline_card_title": "ऑफलाइन प्रवास कार्ड (डाउनलोड)",
