    "packing_climate_note": "सह्याद्री पर्वतरांग (४६३ मी.)",
    "packing_cta_darshan": "दर्शन नियोजनाकडे जा",
    "packing_ctx_desc_all_season": "बिमलाल धाम हे घनदाट जंगलात वसलेले पवित्र स्थान आहे. सात्विक पारंपरिक पोषाख, पादत्राणांसाठी कापडी पिशवी, नियमित औषधे व आपत्कालीन रोख रक्कम बाळगणे आवश्यक आहे.",
    "packing_ctx_desc_monsoon": "सह्याद्रीच्या दाट अरण्यात मुसळधार पाऊस, सततचे धुके आणि गुहेकडील पाषाण पायऱ्यांवर निसरडेपणा असतो. जलरोधक पाँशो व मजबूत ग्रीपची पादत्राणे अत्यावश्यक आहेत.",
    "packing_ctx_desc_summer": "दुपारचे तापमान ३४° ते ३८° सेल्सिअस असते. अरण्यात सावली असली तरी मोकळ्या दर्शन मार्गावर ऊन तीव्र असते. पुरेसे पाणी, सुती कपडे आणि डोक्यावर बांधण्यासाठी सुती गमछा सोबत असावा.",
    "packing_ctx_desc_winter": "अरण्यातील रात्रीचे तापमान १०° ते १४° सेल्सिअसपर्यंत खाली येते आणि दाट दव पडते. महाशिवरात्रीच्या चार प्रहरांच्या रात्रीच्या पूजेसाठी व काकड आरतीसाठी उबदार कपडे व शाल जवळ ठेवावी.",
    "packing_ctx_title_all_season": "संरक्षित अभयारण्य शिष्टाचार (वर्षभर)",
    "packing_ctx_title_monsoon": "पावसाळी हवामान वैशिष्ट्य (जुलै ते ऑक्टोबर)",
    "packing_ctx_title_summer": "उन्हाळी हवामान वैशिष्ट्य (मार्च ते जून)",
