    "seva_btn": "सेवा सहभागाविषयी जाणून घ्या →",
    "seva_desc": "मंदिरातील प्रत्येक सेवा ही केवळ दान नसून आत्मशुद्धी व निसर्ग पूजनाची साधना आहे.",
    "seva_forest_desc": "सह्याद्रीच्या वनराईत साग, वड, पिंपळ व औषधी वनस्पतींचे रक्षण व संवर्धन.",
    "seva_forest_title": "डांग अरण्य वृक्षारोपण",
    "seva_goshala_desc": "देशी डांगी व गीर गोमातेचे संवर्धन, सेंद्रिय चारा आणि अखंड सेवा.",
    "seva_goshala_title": "सुरभी गोसेवा प्रकल्प",
    "seva_note": "सर्व सेवा निष्काम भावनेने चालविल्या जातात. सेवेत सहभागासाठी अथवा अधिक माहितीसाठी मंदिर विश्वस्त कार्यालयाशी संपर्क साधावा.",
    "seva_tag": "निष्काम भक्ती व सेवा",
