    "social_channels_label": "अधिकृत आध्यात्मिक सोशल चॅनेल:",
    "swamiji_awards_desc": "पूज्य स्वामीजींच्या निष्काम अरण्य सेवेचा आणि सनातन धर्म जागृतीचा विविध संप्रदायांकडून व संस्थांकडून झालेला सन्मान.",
    "swamiji_awards_title": "आध्यात्मिक सन्मान व गौरव",
    "swamiji_badge": "૪૦+ વર્ષ વન તપસ્યા",
    "swamiji_btn": "स्वामीजींची जीवनगाथा वाचा →",
    "swamiji_card1_desc": "ડાંગના ગાઢ અરણ્યમાં એકાંતવાસ ભોગવી જંગલનાં પાંદડાં, ફૂલો અને પાણી ગ્રહણ કરી એક વર્ષ, ત્રણ મહિના અને બાર દિવસ ઘોર તપસ્યા કરી.",
    "swamiji_card1_title": "અખંડ મૌન અને કઠોર તપસ્યા",
    "swamiji_card2_desc": "ભગવાન શિવ અને માતા પાર્વતીના સાક્ષાત્કારથી સ્વામીજીને ચાર વેદોનું જ્ઞાન અને યોગ દ્વારા ૮૧ વિદ્યાઓનું જ્ઞાન પ્રાપ્ત થયું.",
    "swamiji_card2_title": "વેદ જ્ઞાન અને ૮૧ વિદ્યાઓ",
    "swamiji_card3_desc": "દારૂ અને તમાકુના વ્યસનમાંથી હજારો લોકોને મુક્ત કરી દીર્ઘકાલીન દર્દીઓને નિઃશુલ્ક આધ્યાત્મિક અને ઔષધીય માર્ગદર્શન આપ્યું.",
    "swamiji_card3_title": "નિઃશુલ્ક વ્યસનમુક્તિ અને આરોગ્ય સેવા",
    "swamiji_card4_desc": "સ્વયંભૂ શિવ અર્ધનરેશ્વર, નાગદેવતા, વાઘોબા, રાધાકૃષ્ણ અને પંચમુખી હનુમાનજીની પવિત્ર પ્રાણપ્રતિષ્ઠા કરી ભક્તિમય ધામનું સર્જન કર્યું.",
    "swamiji_card4_title": "બિમલાલ તુલસીગઢ સ્થાપના",
    "swamiji_desc": "४० वर्षांहून अधिक काळ डांगच्या गहन जंगलात अखंड ध्यानधारणा, आदिवासी समाजाचे उत्थान आणि अर्धनरेश्वर ज्योतिर्लिंगाची पुनर्स्थापना करणारे दिव्य तपस्वी.",
    "swamiji_karya_desc": "आदिवासी समाजाचे आध्यात्मिक उत्थान, गोवंश संवर्धन, डांग अरण्य रक्षण, व्यसनमुक्ती आणि सनातन संस्कृतीचे रक्षण हे पूज्य स्वामीजींच्या जीवनसाधनेचे मुख्य स्तंभ आहेत.",
    "swamiji_karya_title": "पूज्य स्वामीजींचे जीवनकार्य व सेवा संकल्प",
    "swamiji_lead": "ડાંગના પાવન દંડકારણ્યમાં અખંડ શિવ આરાધના, ગોરક્ષા અને આદિવાસી જનકલ્યાણ માટે પોતાનું જીવન સમર્પિત કરનાર સાચા તપસ્વી સંત.",
    "swamiji_name_full": "मठाधीपती प.पू. संत स्वामी अनेकरूपीजी महाराज",
    "swamiji_parichay_dharma": "'सनातन हिंदू धर्मजागृतम्' अभियानाद्वारे ते धर्माचा प्रसार करत आहेत आणि स्थानिक बांधवांना आपल्या संस्कृतीशी जोडून त्यांचे धर्मांतरापासून रक्षण करत आहेत.",
    "swamiji_parichay_heading": "प.पू. संत स्वामी अनेकरूपी महाराज यांचे दिव्य ईश्वरी कार्य",
    "swamiji_parichay_quote": "त्यांनी चार वेदांचे आणि ५१ विविध विद्यांचे सखोल ज्ञान आत्मसात केले, ज्यातून त्यांच्या आजीवन समाजकार्याची मुहूर्तमेढ रोवली गेली. आज स्वामीजींचे हे स्थान महाराष्ट्र, गुजरात, राजस्थान आणि मध्य प्रदेशातील भाविकांसाठी एक प्रमुख आध्यात्मिक केंद्र बनले आहे.",
    "swamiji_parichay_remedies": "ग्रह-नक्षत्र-कालसर्पदोषांवर स्वामीजी खात्रीशीर वैदिक उपाय सुचवतात, तसेच व्यसनमुक्ती आणि मानसिक शांतीसाठी साधकांना सन्मार्ग दाखवतात.",
    "swamiji_parichay_restoration": "प्राचीन आणि नवीन मंदिरांची पुनःस्थापना व शास्त्रोक्त प्राणप्रतिष्ठा करून या पावन क्षेत्राचे चैतन्य जागृत करण्याचे महान कार्य स्वामीजींनी संपन्न केले आहे.",
    "swamiji_parichay_rituals": "मंदिरामध्ये महारुद्र अभिषेक, यज्ञ-याग आणि सत्संग यांसारख्या धार्मिक कार्यांचे आयोजन करून ते भक्तीचा महिमा वाढवत आहेत.",
    "swamiji_parichay_seva": "विशेष म्हणजे, हे सर्व ईश्वरी कार्य स्वामीजी कोणत्याही मानधनाशिवाय म्हणजेच पूर्णतः विनामूल्य करत असून त्यांचा उद्देश केवळ जनकल्याण हाच आहे.",
    "swamiji_parichay_tapasya": "बाल्यवयापासूनच अत्यंत खडतर जप-तप आणि अनुष्ठान करून स्वामीजींनी भगवान महादेव आणि माता पार्वती यांच्याकडून दिव्य वरदान व सिद्धी प्राप्त केल्या आहेत.",
    "swamiji_quote": "“સેવા એ જ સાધના અને ઈશ્વર ભક્તિ એ જ જીવનનો સાચો ઉદ્ધાર છે.”",
    "swamiji_subtitle": "ડાંગના દંડકારણ્યમાં ૪૦ વર્ષથી અખંડ મૌન તપસ્યા અને લોકસેવા કરનાર સિદ્ધ સંત",
    "swamiji_tag": "तपोनिधी मार्गदर्शक",
