    "crowd_classification": "हर रविवार, सोमवार और मंगलवार को उमड़ने वाले हजारों भक्तों के जनसैलाब को देखते हुए मंदिर प्रशासन ने दर्शन व्यवस्था को सुव्यवस्थित किया है। इसमें सामान्य दर्शन, वीआईपी दर्शन, विशेष दर्शन (वरिष्ठ नागरिकों और दिव्यांगों के लिए) और स्थानीय भक्तों के लिए आरक्षित दर्शन श्रेणियाँ बनाई गई हैं।",
