    "fact_when_title": "कब",
    "fact_where_main": "गुफा गर्भगृह",
    "fact_where_sub": "तुलसीगढ़, बिमलाल\nतहसील आहवा, डांग, गुजरात",
    "fact_where_title": "कहाँ",
    "footer_about_desc": "बिमलाल, तह. आहवा, जिला डांग, गुजरात। सनातन संस्कृति, वन संरक्षण और शिव-शक्ति उपासना का पावन केंद्र।",
