    "footer_copyright": "© २०२६ श्री शिव अर्धनारेश्वर नाग ज्योतिर्लिंग मंदिर ट्रस्ट, बिमलाल। सर्वाधिकार सुरक्षित।",
    "footer_links_title": "महत्वपूर्ण कड़ियां",
    "footer_trust_desc": "गुजरात पब्लिक ट्रस्ट एक्ट, १९५० के तहत पंजीकृत। सभी दान आयकर धारा ८०जी के अंतर्गत करमुक्त।",
    "footer_trust_title": "न्यास व पारदर्शिता",
    "gallery_cat_all": "सभी छायाचित्र (All)",
    "gallery_cat_mandir_sohala": "मंदिर उत्सव एवं समारोह (Mandir Sohala)",
    "gallery_cat_news": "समाचार पत्र संग्रह (News Album)",
    "gallery_cat_past_present": "मंदिर अतीत एवं वर्तमान (Past & Present)",
    "gallery_cat_sohala": "मंदिर उत्सव एवं समारोह",
    "gallery_coming_soon": "शीघ्र उपलब्ध होगा",
    "gallery_coming_soon_sub": "इस दीर्घा के छायाचित्र शीघ्र जोड़े जाएंगे।",
    "gallery_upload_btn": "समारोह चित्र जोड़ें (Upload)",
    "gallery_upload_hint": "समारोह छायाचित्र (sohala-01.jpg से sohala-04.jpg) चुनें।",
    "hero_badge": "डांग अरण्य की स्वयंभू पवित्र तपोभूमि",
    "hero_btn_chronicle": "पावन इतिहास पढ़ें",
    "hero_btn_plan": "दर्शन समय व ई-पास",
    "hero_main_desc_1": "गुजरात के डांग जिले में आहवा तालुका के बिलमल में स्थित तुलसीगढ़ जैसे पवित्र स्थान पर, हमारे आदरणीय गुरु स्वामी अनेकरूपी महाराज के मार्गदर्शन में भगवान शिव अधनारेश्वर की मूर्ति स्थापित की गई है। पुराणों के अनुसार, उस समय इस क्षेत्र को 'दंडकारण्य' क्षेत्र के रूप में जाना जाता था। यहाँ मुख्य रूप से नाग देवता और वाघ (बाघ) देवता की मूर्तियाँ भी स्थापित की गई हैं। इसके साथ ही यहाँ राधा-कृष्ण, विठ्ठल-रुक्मिणी, राम-लक्ष्मण-जानकी, हनुमान, पंचमुखी हनुमान, खंडेराव महाराज और भगवान गणेश की मूर्तियाँ भी विराजमान हैं। पूरे भारत में एकमात्र 'शिव अधनारेश्वर नाग ज्योतिर्लिंग धाम' हमें केवल तुलसीगढ़, बिलमल में ही देखने को मिलता है।",
    "hero_main_desc_2": "इस पावन धाम में आने पर आपको मंदिर और स्वामीजी के सान्निध्य में दिव्यता की अनुभूति होती है। यहाँ आपको अन्य भक्तों के श्रद्धापूर्ण और अलौकिक अनुभवों का साक्षात दर्शन होगा।",
    "hero_presence_tag": "सह्याद्रि पर्वतमाला में प्रकृत्तिरूप शिव का साक्षात अनुभव",
    "hero_subtitle": "श्री शिव अर्धनारेश्वर नाग ज्योतिर्लिंग धाम — सघन वन की पाषाण गुफा गर्भगृह, अखंड वैदिक नामघोष और पूज्य स्वामीजी की ४० वर्षों की मौन प्रकृति तपस्या।",
    "hero_threshold_text": "जंगल जैसे प्रवेश करता है, वैसे ही श्रद्धा से प्रवेश करें.",
    "hero_title": "जहाँ वन ही प्रार्थना बन जाता है।",
    "journey_arrival_desc": "पार्किंग में वाहन खड़ा करें। मुख्य स्वागत केंद्र पर दर्शन पास दिखाएं। वरिष्ठ नागरिकों हेतु सहायक कार्ट उपलब्ध है।",
    "journey_arrival_title": "३. धाम आगमन पश्चात",
    "journey_before_desc": "सात्विक पारंपरिक वस्त्र साथ लें, आधार कार्ड / पहचान पत्र रखें और डिजिटल दर्शन पास डाउनलोड कर लें।",
