    "mahashivratri_spotlight_badge": "वार्षिक महासंगम · प्रमुख महापर्व",
    "mahashivratri_spotlight_desc": "सह्याद्रि के सघन वन में लाखों भक्तों का संगम, अखंड धूणी दर्शन, चार प्रहर की पाषाण गुफा महापूजा और चौबीसों घंटे निःशुल्क अन्नपूर्णा महाप्रसाद।",
    "mahashivratri_spotlight_note": "आगामी महाशिवरात्रि उत्सव की आधिकारिक तिथि व कार्यक्रम पत्रिका ट्रस्ट कार्यालय द्वारा घोषित होते ही यहाँ प्रकाशित की जाएगी।",
    "mahashivratri_spotlight_timing": "૪ દિવસીય અખંડ ઉત્સવ · માઘ વદ ચતુર્દશી",
    "mahashivratri_spotlight_title": "महाशिवरात्रि महापर्व — ४ दिन चौबीसों घंटे अखंड भक्ति महोत्सव",
    "mandir_cave_desc": "प्राकृतिक पाषाण गुफा में स्वयंभू नाग शिवलिंग का वास है, जहाँ अविरत वैदिक नामघोष व शांति में दर्शन होता है।",
    "mandir_cave_title": "स्वयंभू पाषाण गुफा गर्भगृह",
    "mandir_discovery_desc": "१९८० के दशक में परमपूज्य संत स्वामी अनेकरूपीजी महाराज ने गहन वन में इस स्वयंभू स्थल को प्रकट कर अखंड धूणी व उपासना की स्थापना की।",
    "mandir_discovery_title": "पावन पुनरुत्थान इतिहास",
    "mandir_info_desc": "सह्याद्रि की गोद में तुलसीगड पहाड़ी पर सघन डांग अरण्य में स्वयंभू अर्धनारेश्वर नाग ज्योतिर्लिंग प्रकट हुआ है। पाषाण गुफा से अविरल बहने वाला पाषाण जलप्रपात और शिव-शक्ति का अद्वैत स्वरूप भक्तों को अलौकिक शांति प्रदान करता है।",
    "mandir_info_title": "श्री धाम व गुफा गर्भगृह परिचय",
    "mandir_parichay_ancient": "पुराणों के अनुसार, यह क्षेत्र प्राचीन 'दंडकारण्य' का हिस्सा था। यहाँ जप, तप और अनुष्ठान करने से विशेष पुण्य फल की प्राप्ति होती है।",
    "mandir_parichay_divine": "इस क्षेत्र में नाग देवताओं का अलौकिक वास है; आध्यात्मिक रूप से सौभाग्यशाली भक्तों को समय-समय पर उनके दर्शन प्राप्त हुए हैं।",
    "mandir_parichay_establishment": "गुजरात के डांग जिले में स्थित तुलसीगढ़ के पवित्र धाम में, पूजनीय स्वामी अनेकरूपी महाराज के मार्गदर्शन में भगवान शिव अधनारेश्वर की स्थापना की गई है।",
    "mandir_parichay_heading": "तुलसीगढ़: दिव्य ऊर्जा का पावन केंद्र",
    "mandir_parichay_historical": "पास के बिल्मल गाँव में पूर्व काल में बिल्व (बेल) पत्रों का विशाल जंगल हुआ करता था। हालांकि वर्तमान में वृक्षों की कटाई के कारण यह कम हो गया है, किंतु आज भी यहाँ भगवान शिव और माता शक्ति की दिव्य उपस्थिति का अनुभव होता है।",
    "mathadhipati_title": "मठाधीपति प.पू. संत स्वामी अनेकरूपीजी महाराज",
    "nag_dwar_sub": "वन में जिस पावन भाव से प्रवेश करते हैं, उसी श्रद्धा से इस पावन धाम में प्रवेश करें।",
    "nag_dwar_title": "नाग द्वार · पवित्र अरण्य प्रवेश",
