    "nav_trust": "दान व न्यास",
    "nav_yatra": "यात्रा व संपर्क",
    "news_placeholder_desc": "मंदिर ट्रस्ट की आधिकारिक सूचनाएँ, यात्रा मार्गदर्शिका और धर्मसभा के परिपत्र यहाँ अद्यतन किए जाते हैं। तत्काल सूचना हेतु आधिकारिक चैनलों से जुड़ें।",
    "news_placeholder_title": "आगामी उत्सव व कार्यक्रम सूचना",
    "news_section_tag": "आधिकारिक सूचना व समाचार",
    "news_section_title": "मंदिर समाचार व सूचना पट्ट",
    "niyam_1": "1. पवित्रता: प्रवेश से पूर्व स्नान कर तन-मन शुद्ध करें। परिसर में थूकना या कचरा फैलाना वर्जित है।",
    "niyam_10": "10. मंदिर परिसर में प्लास्टिक की थैलियों और प्लास्टिक वस्तुओं का उपयोग सख्त वर्जित है। परिसर स्वच्छ रखें। कूड़ा केवल कूड़ेदान में ही डालें।",
    "niyam_11": "11. मंदिर परिसर में जंगली जानवर हो सकते हैं, इसलिए अकेले न घूमें और उन्हें परेशान न करें। जंगली जानवरों को कोई भी भोजन न खिलाएं, यह खतरनाक साबित हो सकता है। जंगली जानवरों की उपस्थिति के कारण सूर्यास्त के बाद परिसर में घूमने से बचें।",
    "niyam_2": "2. जूते-चप्पल: पादत्राण मंदिर के बाहर निश्चित स्थान पर ही उतारें।",
    "niyam_3": "3. वेशभूषा: भारतीय संस्कृति के अनुरूप मर्यादित वस्त्र पहनें। छोटे वस्त्र पहनकर प्रवेश न करें।",
    "niyam_4": "4. शांति और अनुशासन: मौन रहें। मोबाइल बंद रखें। शोर मचाना या दौड़ना मना है।",
    "niyam_5": "5. गर्भगृह: मूर्तियों को स्पर्श न करें। प्रदक्षिणा सदैव घड़ी की सुई की दिशा (Clockwise) में करें।",
    "niyam_6": "6. नशा निषेध: मदिरा, गुटखा, सिगरेट या किसी भी नशीले पदार्थ का सेवन सख्त मना है।",
    "niyam_7": "7. छायाचित्रण: अनुमति के बिना गर्भगृह या मूर्तियों की फोटो या वीडियो न बनाएं।",
    "niyam_8": "8. दान: दान केवल दानपात्र में ही डालें।",
    "niyam_9": "9. सूतक एवं श्राद्ध: सूतक काल (10-13 दिन) या दशक्रिया/श्राद्ध के दौरान मंदिर प्रवेश वर्जित है। शुद्धिकरण विधि के पश्चात ही पूजा-अर्चना करें।",
    "niyam_heading": "मंदिर नियमावली",
    "niyamavali_tag": "नाग रक्षा कवच · पवित्र अरण्य अनुशासन",
    "niyamavali_title": "मंदिर नियमावली व आचारसंहिता",
