    "seva_btn": "सेवा सहयोग के विषय में जानें →",
    "seva_desc": "मंदिर की प्रत्येक सेवा केवल दान नहीं, अपितु आत्म-कल्याण और प्रकृति वंदना की पावन साधना है।",
    "seva_forest_desc": "सह्याद्रि के जंगलों में सागवान, बरगद, पीपल व औषधीय वनस्पतियों का संरक्षण।",
    "seva_forest_title": "डांग अरण्य वृक्षारोपण",
    "seva_goshala_desc": "देसी डांगी व गिर गोवंश का संरक्षण, प्राकृतिक चारा और संवर्धन।",
    "seva_goshala_title": "सुरभि गोसेवा प्रकल्प",
    "seva_note": "सभी सेवाएँ निष्काम भाव से संचालित की जाती हैं। सेवा में सहभागिता अथवा अधिक जानकारी हेतु मंदिर विश्वस्त कार्यालय से संपर्क करें।",
    "seva_tag": "निष्काम भक्ति व सेवा",
