    "social_channels_label": "आधिकारिक आध्यात्मिक सोशल चैनल:",
    "swamiji_awards_desc": "पूज्य स्वामीजी की निष्काम अरण्य सेवा व सनातन धर्म जागृति का विभिन्न संप्रदायों व संस्थाओं द्वारा किया गया सम्मान।",
    "swamiji_awards_title": "आध्यात्मिक सम्मान व गौरव",
    "swamiji_badge": "૪૦+ વર્ષ વન તપસ્યા",
    "swamiji_btn": "स्वामीजी की जीवनगाथा पढ़ें →",
    "swamiji_card1_desc": "ડાંગના ગાઢ અરણ્યમાં એકાંતવાસ ભોગવી જંગલનાં પાંદડાં, ફૂલો અને પાણી ગ્રહણ કરી એક વર્ષ, ત્રણ મહિના અને બાર દિવસ ઘોર તપસ્યા કરી.",
    "swamiji_card1_title": "અખંડ મૌન અને કઠોર તપસ્યા",
    "swamiji_card2_desc": "ભગવાન શિવ અને માતા પાર્વતીના સાક્ષાત્કારથી સ્વામીજીને ચાર વેદોનું જ્ઞાન અને યોગ દ્વારા ૮૧ વિદ્યાઓનું જ્ઞાન પ્રાપ્ત થયું.",
    "swamiji_card2_title": "વેદ જ્ઞાન અને ૮૧ વિદ્યાઓ",
    "swamiji_card3_desc": "દારૂ અને તમાકુના વ્યસનમાંથી હજારો લોકોને મુક્ત કરી દીર્ઘકાલીન દર્દીઓને નિઃશુલ્ક આધ્યાત્મિક અને ઔષધીય માર્ગદર્શન આપ્યું.",
    "swamiji_card3_title": "નિઃશુલ્ક વ્યસનમુક્તિ અને આરોગ્ય સેવા",
    "swamiji_card4_desc": "સ્વયંભૂ શિવ અર્ધનરેશ્વર, નાગદેવતા, વાઘોબા, રાધાકૃષ્ણ અને પંચમુખી હનુમાનજીની પવિત્ર પ્રાણપ્રતિષ્ઠા કરી ભક્તિમય ધામનું સર્જન કર્યું.",
    "swamiji_card4_title": "બિમલાલ તુલસીગઢ સ્થાપના",
    "swamiji_desc": "४० से अधिक वर्षों तक डांग के गहन वन में अखंड साधना, वनवासी समाज का कल्याण और अर्धनारेश्वर ज्योतिर्लिंग की पुनःप्रतिष्ठा करने वाले दिव्य तपस्वी।",
    "swamiji_karya_desc": "आदिवासी समाज का आध्यात्मिक उत्थान, गोवंश संवर्धन, डांग वन संरक्षण, व्यसनमुक्ति और सनातन संस्कृति का रक्षण पूज्य स्वामीजी की साधना के मुख्य स्तंभ हैं।",
    "swamiji_karya_title": "पूज्य स्वामीजी का जीवनकार्य व सेवा संकल्प",
    "swamiji_lead": "ડાંગના પાવન દંડકારણ્યમાં અખંડ શિવ આરાધના, ગોરક્ષા અને આદિવાસી જનકલ્યાણ માટે પોતાનું જીવન સમર્પિત કરનાર સાચા તપસ્વી સંત.",
    "swamiji_name_full": "मठाधीपति प.पू. संत स्वामी अनेकरूपीजी महाराज",
    "swamiji_parichay_dharma": "'सनातन हिंदू धर्मजागृतम्' अभियान के द्वारा वे धर्म की रक्षा कर रहे हैं और स्थानीय समाज को धर्मपरिवर्तन के कुचक्र से बचाकर उन्हें अपनी जड़ों से जोड़ रहे हैं।",
    "swamiji_parichay_heading": "प.पू. संत स्वामी अनेकरूपी महाराज का अलौकिक मिशन",
    "swamiji_parichay_quote": "उन्होंने चारों वेदों और ५१ विभिन्न विद्याओं का गहन ज्ञान प्राप्त किया, जो उनके आजीवन समाज सेवा के मिशन का आधार बना। स्वामीजी का यह धाम महाराष्ट्र, गुजरात, राजस्थान और मध्य प्रदेश के भक्तों के लिए एक प्रमुख आध्यात्मिक केंद्र के रूप में कार्य करता है।",
    "swamiji_parichay_remedies": "ग्रह दोष, नक्षत्र दोष और कालसर्पदोष जैसी बाधाओं का वे सटीक वैदिक समाधान प्रदान करते हैं और दुखी जनों को मानसिक शांति की ओर ले जाते हैं।",
    "swamiji_parichay_restoration": "प्राचीन एवं नवीन मंदिरों की पुनःस्थापना और भव्य प्राण-प्रतिष्ठा के माध्यम से स्वामीजी ने इन पावन तीर्थों में पुनः प्राण फूँके हैं।",
    "swamiji_parichay_rituals": "स्वामीजी के सान्निध्य में महारुद्र अभिषेक, विशाल यज्ञ और अखंड सत्संग जैसे अनुष्ठान निरंतर चलते रहते हैं, जिससे लोक-कल्याण का मार्ग प्रशस्त होता है।",
    "swamiji_parichay_seva": "सबसे वंदनीय बात यह है कि स्वामीजी यह समस्त पावन कार्य पूर्णतः निःशुल्क करते हैं, जिसका ध्येय केवल मानवता की सेवा है।",
    "swamiji_parichay_tapasya": "बाल्यावस्था से ही अत्यंत कठिन साधना और जप-तप के माध्यम से स्वामीजी ने देवाधिदेव महादेव और माता पार्वती से दिव्य सिद्धियाँ प्राप्त की हैं।",
    "swamiji_quote": "“સેવા એ જ સાધના અને ઈશ્વર ભક્તિ એ જ જીવનનો સાચો ઉદ્ધાર છે.”",
    "swamiji_subtitle": "ડાંગના દંડકારણ્યમાં ૪૦ વર્ષથી અખંડ મૌન તપસ્યા અને લોકસેવા કરનાર સિદ્ધ સંત",
    "swamiji_tag": "तपोनिधि मार्गदर्शक",
