    "crowd_accessibility": "Special facilities, including wheelchair access and dedicated parking, are available for senior citizens and physically challenged devotees.",
    "crowd_amenities": "For your convenience, the temple provides clean restrooms, purified drinking water, and quiet areas for rest and reflection.",
    "crowd_booking": "While devotees are encouraged to register online before their visit, the administration has reserved emergency slots for first-time visitors or those in urgent situations to ensure no one is inconvenienced.",
    "crowd_classification": "Due to the large influx of thousands of devotees every Sunday, Monday, and Tuesday, the temple administration has implemented a structured Darshan system. This includes categories for General Darshan, VIP Darshan, Special Assistance (for Seniors & Physically Challenged), and Reserved Slots for Local Devotees.",
    "crowd_free": "Most importantly, the entire Darshan process is provided completely free of charge for every devotee.",
    "crowd_heading": "Crowd Management & Darshan Guidelines",
    "crowd_sanctity": "To maintain the temple's sanctity, please observe silence at all times. Before entering the inner sanctum, all footwear and leather items (belts, wallets, etc.) must be deposited in the lockers located near the entrance. Your cooperation in maintaining discipline is appreciated.",
    "darshan_cat_general_desc": "Free sanctum access for all pilgrims. Zero VIP charges or commercial fees. Available via digital pass or direct queue.",
    "darshan_cat_general_title": "1. General Darshan Suvidha",
    "darshan_cat_local_desc": "Dedicated visiting hours respecting the traditions and agricultural rhythms of local Dang villagers and tribal communities.",
    "darshan_cat_local_title": "3. Local Pilgrim Darshan (Dang & Tribal Villages)",
    "darshan_cat_special_desc": "Tatkal priority assistance, wheelchair support, and ashram volunteers dedicated for senior citizens and differently-abled pilgrims.",
    "darshan_cat_special_title": "2. Special Assisted Darshan (Aged & Disabled)",
    "darshan_cat_vip_desc": "Notice: VIP Darshan is NOT available for public purchase or self-booking. It is strictly allocated under temple trust administrative protocols. No booking fee exists.",
    "darshan_cat_vip_notice": "VIP Darshan is for administrative information only — no public booking or fee is ever accepted.",
    "darshan_cat_vip_title": "4. VIP Darshan Information (Public View-Only)",
    "darshan_desc": "Darshan at Bimlal Dham is entirely free. There are no commercial VIP tickets or monetized priority lanes — all devotees approach the subterranean sanctum with equal reverence.",
    "darshan_highlight_construction": "The temple is currently undergoing construction and renovation. Due to this, visiting devotees are staying in the temple shed and courtyard area. We appreciate your patience and cooperation during this period of development.",
    "darshan_highlight_divine": "Divine Blessings: He offers spiritual guidance and resolves the problems of devotees free of charge, bestowing his divine blessings upon all who seek his presence.",
    "darshan_highlight_morning": "Morning Presence: Swamiji graces the Gadi (Sinhasan) daily from 6:00 AM onwards to bless the devotees.",
    "darshan_highlight_selfless": "Selfless Service: Swamiji remains present until the final devotee holding an evening darshan receipt has been attended to.",
    "darshan_tag": "Pilgrim Guidance & Information",
    "darshan_title": "The Sacred Darshan",
    "donation_80g_notice": "Shree Shiv Ardhanreshwari Nag Jyotirling Mandir Trust, Bimlal is registered under Gujarat Public Trusts Act, 1950 (Reg. No.: E / 169 / Dang - 19/11/2014). Contributions qualify for tax exemption under Section 80G.",
    "donation_bank_placeholder": "Official Trust Bank Account and IFSC verification will be listed here upon administrative release.",
    "donation_bank_title": "Official Donation Guidance",
    "donation_fraud_warning": "Donations must be made ONLY via the official temple bank account or portal QR code. Do not give cash to any private individual.",
    "donation_title": "Sacred Seva Contribution & Donation",
    "event_1_desc": "Annual temple establishment observance marked by sacred Rudrabhishek, dhwaja poojan, and grand community feast.",
    "event_1_tithi": "Annual Consecration Anniversary",
    "event_1_title": "1. Mandir Vardhapan Din Sohala",
    "event_2_desc": "The pinnacle temple celebration featuring all-night four-prahar worship, sacred havan, and holy darshan.",
    "event_2_detail": "Mahashivratri holds the highest place among all festivals celebrated at Shri Kshetra Bilmal Tulsigad. On this occasion, the temple hosts a three-and-a-half-day Namyajna, the Akhand Shiv-Hari Naam Saptah, Shiv Mahapuran Katha, and Shiv-Hari Kirtan Bhajans, along with various religious and cultural programs. The Maha Aarti performed at noon and midnight on Mahashivratri is considered especially auspicious. Devotees believe that on this day, Lord Shiva and Parvati manifest directly in the form of Swamiji. Devotees undertake foot pilgrimages (Dindi) and Kavad Yatras from various regions for this festival. Mahaprasad is arranged for all devotees across the four days of the festival, with lakhs of devotees participating. On the evening of Mahashivratri, P.P. Sant Swami Anekrupi Maharaj delivers a nectar-like discourse, and the program concludes the next day with Kaliya Kirtan.",
    "event_2_tithi": "Magha Krishna Chaturdashi · 4-Day Grand Festival",
    "event_2_title": "2. Mahashivratri Mahaparva Sohala",
    "event_2_why": "The highest revered festival at Bilmal, where devotees experience the living presence of Shiva-Parvati in Swamiji amidst four days of unbroken worship.",
    "event_3_desc": "Month-long sacred Bilva Patra offerings, Special Monday Maha Aarti, and holy chanting amidst Sahyadri monsoons.",
    "event_3_tithi": "Holy Month of Shravan · Special Somwar",
    "event_3_title": "3. Pavitra Shravan Maas Sohala",
    "event_3_why": "Month-long unbroken Bilva offerings, Monday Maha Aartis, and foot kavad yatras arriving through the monsoon mist of the Sahyadri mountains.",
    "event_4_desc": "A ceremony of reverence honoring Pujya Swamiji’s lifelong tapasya, attended by saints, elders, and devotees.",
    "event_4_tithi": "Swamiji's Spiritual Milestone Observance",
    "event_4_title": "4. Swamiji Abhishtchintan Sohala",
    "event_5_desc": "Paying homage to the divine Guru lineage with padya poojan, spiritual discourses, and guided meditation.",
    "event_5_detail": "Gurupurnima is as important a festival as Mahashivratri and Navratri for the Shivshakti family at Shri Kshetra Bilmal Tulsigad. During this festival, the disciple family performs Shodashopachara Puja of P.P. Sant Swami Anekrupi Maharaj amidst mantras chanted by the Brahmin community. The darshan ceremony begins after the Aarti of Shri Guru, past noon. Guru means 'guide' and Purnima means 'light' — the knowledge received from the Guru illuminates life. It is a day to express gratitude toward the Guru. True Gurupujan means imbibing the knowledge given by the Guru and striving to bring it into practice — this constant gratitude and service toward the Guru is the true Gurudakshina.",
    "event_5_tithi": "Ashadha Shukla Purnima",
    "event_5_title": "5. Gurupurnima Utsav Sohala",
    "event_5_why": "Equally revered as Mahashivratri for the Bimlal family, devoted to expressing gratitude and performing sacred Shodashopachara pooja of Pujya Swamiji.",
    "event_6_desc": "Nine days of sacred Shakti worship honoring the feminine divine half of Ardhanarishwara with Chandi havan.",
    "event_6_tithi": "Ashwin Shukla Pratipada to Navami",
    "event_6_title": "6. Sharadiya Navratri Sohala",
    "event_6_why": "Nine sacred days honoring the Shakti half of Ardhanarishwara with unbroken Ghatasthapana, Durga Saptashati recitation, and Shatachandi Mahayajna.",
    "event_7_desc": "Continuous Vedic chanting, Mahamrityunjaya japa, and sacred fire rituals invoking universal peace and welfare.",
    "event_7_tithi": "Annual Maharudra Swahakar Chanting",
    "event_7_title": "7. Akhand Vedic Anusthan Sohala",
