    "hero_badge": "Sacred Forest Tapobhoomi of Dang",
    "hero_btn_chronicle": "Read Sacred Chronicle",
    "hero_btn_plan": "Darshan Timings & Slip",
    "hero_main_desc_1": "At the holy site of Tulsigad in Bilmal, located in the Ahwa taluka of Dang district, Gujarat, the idol of Lord Shiv Ardhanareshwari has been installed under the guidance of our revered guru Swami Anekrupi Maharaj. According to the Puranas, this region was known as the Dandakaranya area at that time. Mainly idols of Nag (Serpent) and Wagh (Tiger) deities have also been established here. Also additionally idols of Radha Krishna, Vitthal Rukmini, Ram Lakshman Janki, Hanuman, Panchamukhi Hanuman, Khanderav Maharaj, and Lord Ganesh are also established here. India's only Shiv Ardhanareshwari Nag Jyotirlinga Dham can be found exclusively here at Tulsigad, Bilmal.",
    "hero_main_desc_2": "As you step into this holy place, you will experience a profound sense of peace and divinity within the temple and Swamiji. It is a sanctuary where the divine stories and experiences of every devotee come to life.",
    "hero_presence_tag": "Living experience of Shiva & Shakti in the ancient Sahyadri forest",
    "hero_subtitle": "Shree Shiv Ardhanreshwari Nag Jyotirling Dham — subterranean cave sanctum, unbroken Vedic chanting, and Pujya Swamiji's 40-year silent ecological tapasya.",
    "hero_threshold_text": "Enter as the forest enters — with reverence.",
    "hero_title": "Where the forest becomes prayer.",
    "journey_arrival_desc": "Park at designated lot, present digital QR pass at reception counter. Wheelchairs and assisted carts available for elders.",
    "journey_arrival_title": "3. On Arrival (Sanctuary Entry)",
    "journey_before_desc": "Pack traditional modest clothes, carry valid identity proof, and download your verified digital darshan pass.",
    "journey_before_title": "1. Before You Leave (Preparation)",
    "journey_way_desc": "Nearest railhead: Waghai (32 km) or Bilimora (85 km). Ahwa is the central transport hub with regular buses and private vehicles.",
    "journey_way_title": "2. On the Way (Routes)",
