    "mahashivratri_spotlight_badge": "Grand Annual Congregation · Pinnacle Festival",
    "mahashivratri_spotlight_desc": "Hundreds of thousands of devotees gather in the Sahyadri forest for sacred dhuni darshan, 4-prahar sanctum pujas, and round-the-clock free Annapurna Mahaprasad.",
    "mahashivratri_spotlight_note": "Official schedule and approved tithi dates will be published here upon formal release by the temple trust.",
    "mahashivratri_spotlight_timing": "૪ દિવસીય અખંડ ઉત્સવ · માઘ વદ ચતુર્દશી",
    "mahashivratri_spotlight_title": "Mahashivratri Mahaparva — 4-Day 24-Hour Spiritual Festival",
    "mandir_cave_desc": "The self-manifested Nag Jyotirling rests in a natural stone cave, immersed in perpetual Vedic chanting and profound silence.",
    "mandir_cave_title": "Swayambhu Cave Sanctum",
    "mandir_discovery_desc": "In the 1980s, Param Pujya Sant Swami Anekarupiji Maharaj re-established this ancient forest cave shrine through continuous silent tapasya.",
    "mandir_discovery_title": "Sacred Rediscovery & Heritage",
    "mandir_info_desc": "Nestled on Tulsigad hill within the dense Dang forest sanctuary, the self-manifested Ardhanarishwar Nag Jyotirling unites the divine masculine and feminine. A perennial subterranean spring cascades through the ancient stone cave sanctum.",
    "mandir_info_title": "Sacred Shrine & Subterranean Sanctum",
    "mandir_parichay_ancient": "According to the Puranas, this land was part of the legendary Dandakaranya forest. It is a powerful center for Japa, Tapa, and Anushthan, where spiritual practices yield exceptional divine blessings.",
    "mandir_parichay_divine": "The region is graced by the mystical presence of Nag Devtas (Serpent Deities); devotees with deep spiritual merit have often been blessed with their sightings here.",
    "mandir_parichay_establishment": "At the holy site of Tulsigad in Bilmal, Dang district, Gujarat, the divine idol of Lord Shiv Ardhanareshwari was established under the guidance of the revered Swami Anekrupi Maharaj.",
    "mandir_parichay_heading": "Tulsigad: The Sacred Abode of Divine Energy",
    "mandir_parichay_historical": "The adjacent village of Bilmal was once home to a vast forest of Bilva (Bael) trees. While deforestation has significantly reduced this forest, the site remains a sanctuary where one can profoundly feel the divine union of Lord Shiva and Mata Shakti.",
    "mathadhipati_title": "Mathadhipati Param Pujya Sant Swami Anekarupiji Maharaj",
    "nag_dwar_sub": "Enter as the forest enters — with quiet reverence and deep devotion.",
    "nag_dwar_title": "Nag Dwar · Sacred Forest Threshold",
