    "news_placeholder_desc": "Official circulars, pilgrim advisories, and trust announcements are posted here. Devotees may follow verified official social channels for real-time updates.",
    "news_placeholder_title": "Upcoming Festival & Event Circulars",
    "news_section_tag": "Official News & Peeth Announcements",
    "news_section_title": "Sanctuary News & Notice Board",
    "niyam_1": "1. Purity: Bathe and ensure physical and mental purity before entering. Do not litter or spit.",
    "niyam_10": "10. Plastic bags and plastic items are strictly prohibited within the temple premises. Keep the premises clean. Dispose of waste only in the designated dustbins.",
    "niyam_11": "11. Wild animals may be present in the vicinity; avoid walking alone and do not disturb or provoke them. Do not feed the wild animals. It is dangerous for both you and the animal. Due to wildlife activity, avoid wandering around the premises after sunset.",
    "niyam_2": "2. Footwear: Leave shoes/sandals at the designated stand outside.",
    "niyam_3": "3. Dress Code: Wear modest, traditional Indian attire. Avoid short or revealing clothes.",
    "niyam_4": "4. Silence: Maintain silence. Keep mobiles off or on silent. Do not shout or run.",
    "niyam_5": "5. Sanctum: Do not touch the idols. Always perform circumambulation (Pradakshina) clockwise.",
    "niyam_6": "6. Prohibitions: Alcohol, tobacco, cigarettes, and all intoxicants are strictly prohibited.",
    "niyam_7": "7. Photography: Do not take photos or videos of the sanctum/idols without permission.",
    "niyam_8": "8. Donations: Place offerings only in the donation box (Dan-peti).",
    "niyam_9": "9. Sutak & Rituals: Persons observing Sutak (10-13 days after a birth/death) or Dashkriya/Shradhh periods should not enter the temple or offer food. Temple entry and worship are permitted only after the purification ritual (Shuddhikaran).",
    "niyam_heading": "Temple Guidelines for Devotees",
    "niyamavali_tag": "Sacred Sanctuary Discipline & Pilgrim Ethics",
    "niyamavali_title": "Mandir Niyamavali & Pilgrim Code of Conduct",
    "official_channels_title": "Verified Official Channels",
    "official_contact_phone": "+91 94280 13445",
    "official_donation_safety_notice": "⚠ Official Notice: This website (sdp-2-0.vercel.app) is the only official online channel for donations to Shiv Ardhanreshwari Nag Jyotirling Dham, Bimlal. Please do not send donations through any other website, app, or individual claiming to represent the Dham. For verification, contact the temple directly.",
    "official_instagram_label": "Official Instagram Handle",
    "official_reg_badge": "Reg. No.: E / 169 / Dang - 19/11/2014",
    "official_trust_badge": "Govt. Registered Public Trust · Free Darshan",
    "official_youtube_label": "Official YouTube Channel",
    "offline_card_desc": "Because cellular connectivity is patchy across the Dang forest, save or print this offline travel guide card.",
    "offline_card_title": "Offline Travel Card (Download)",
    "packing_badge": "Seasonal Pilgrim Packing Checklist · Dang Sanctuary",
    "packing_climate_note": "Sahyadri Mountain Range (Elev. 463m)",
    "packing_cta_darshan": "Plan Your Darshan",
    "packing_ctx_desc_all_season": "Bimlal Dham is set inside an untouched mountain forest sanctuary. Modest traditional attire, reusable shoe bags, personal medicines, and cash are year-round necessities.",
    "packing_ctx_desc_monsoon": "Torrential downpours, dense valley fog, and slippery stone steps leading to the cave sanctum. Waterproof rainwear and anti-slip footwear are vital.",
    "packing_ctx_desc_summer": "Daytime temperatures reach 34°C–38°C. While forest canopy provides shade, open temple courtyards get hot. Breathable cottons, hydration flasks, and sun scarves are recommended.",
    "packing_ctx_desc_winter": "Forest temperatures dip to 10°C–14°C with heavy night dew. Thermal layers, shawls, and night torches are essential for Mahashivratri's 4-prahar night vigils and early morning Kakad Aarti.",
    "packing_ctx_title_all_season": "Sacred Forest Code of Conduct (Year-Round)",
    "packing_ctx_title_monsoon": "Monsoon Microclimate (July to October)",
    "packing_ctx_title_summer": "Summer Microclimate (March to June)",
    "packing_ctx_title_winter": "Winter Microclimate (November to February)",
    "packing_eco_note": "Dang is a protected wildlife sanctuary — kindly keep the forest plastic-free and maintain sacred silence.",
    "packing_item_all_season_1_desc": "Respects ancient cave sanctum sanctity (shoulders and knees reverently covered).",
