    "packing_item_all_season_2_desc": "Stores your footwear cleanly at designated stands without misplacement.",
    "packing_item_all_season_2_title": "Cloth Footwear Storage Bag",
    "packing_item_all_season_3_desc": "Carry 3–4 days personal medications; nearest medical pharmacies are at Ahwa and Waghai.",
    "packing_item_all_season_3_title": "Personal Prescription Medicines",
    "packing_item_all_season_4_desc": "Mobile cellular network (UPI/QR) can be intermittent in deep forest valleys.",
