    "packing_item_summer_5_desc": "Protects bare feet when walking across sun-heated stone courtyards in the afternoon.",
    "packing_item_summer_5_title": "Cotton Socks for Heated Stone Steps",
    "packing_item_winter_1_desc": "Shields against 10°C–14°C cold mountain drafts and heavy forest evening dew.",
    "packing_item_winter_1_title": "Pure Woolen Shawl / Sweater",
    "packing_item_winter_2_desc": "Essential for devotees observing all-night 4-prahar Mahashivratri worship and Kakad Aarti.",
    "packing_item_winter_2_title": "Thermal Layers for Night Vigil",
    "packing_item_winter_3_desc": "Illuminates dark forest paths during early dawn or post-dusk movements safely.",
    "packing_item_winter_3_title": "LED Torch or Headlamp",
