    "rule_1_desc": "Modest traditional Indian clothing is mandatory. Dhoti/Kurta or modest attire for men; Saree or Salwar Kameez for women. Shorts and revealing clothing are strictly prohibited.",
    "rule_1_title": "1. Pilgrim Dress Code",
    "rule_2_desc": "Maintain silence inside the cave sanctum. Photography and mobile phone usage near the holy lingam are strictly prohibited.",
    "rule_2_title": "2. Sanctum Discipline & Conduct",
    "rule_3_desc": "Pilgrims undertaking the sacred 16-Vari commitment must observe pure vegetarian diet, continuous chanting, and humble conduct.",
    "rule_3_title": "3. 16 Vari Pilgrimage Vow Rules",
    "rule_4_desc": "Zero tolerance for alcohol, smoking, or tobacco. 100% plastic-free zone. Do not wander alone in forest trails after sunset for wildlife safety.",
    "rule_4_title": "4. Sanctuary & Forest Conservation",
    "rule_5_desc": "All trustees, staff, and volunteers must serve pilgrims with utmost humility, patience, and selfless devotion.",
    "rule_5_title": "5. Volunteer & Community Code",
    "rule_6_desc": "Park vehicles only in designated trust parking zones. Honking in the silent forest sanctuary is strictly prohibited.",
    "rule_6_title": "6. Vehicle Parking & Traffic Rules",
    "sacred_shloka": "Reliever of sorrow, pain and hardship... The abode of eternal bliss, the ocean of Swami’s grace !!",
    "sanctuary_sub": "Bimlal Sanctuary · Dang, Gujarat",
    "sankalp_accordion_close": "Collapse Affirmation",
    "sankalp_accordion_open": "Read Full Daily Affirmation",
    "sankalp_author": "— Param Pujya Sant Swami Anekrupi Maharaj",
    "sankalp_mantra": "ॐ अनेकरूपाय नमः । ॐ नमः शिवाय ।",
    "sankalp_mantra_sub": "Chant with quiet breath at Brahmamuhurta",
    "sankalp_quote": "“Protect every ancient tree of Dang as living Shiva lingam. Feed the cow, speak with patience, chant with unhurried breath. In the silence of the forest, the eternal Ardhanarishwara reveals itself.”",
    "sankalp_tag": "Dainik Sankalp · Daily Contemplation",
    "seva_10_desc": "Safeguarding tribal communities from religious exploitation while honoring and revitalizing indigenous spiritual roots.",
    "seva_10_detail": "Dham is active in saving society from the threat of conversion by enticement or deceit. By explaining the superiority of our original Hindu Dharma and providing social support, the important work of keeping people connected to their culture is done through this, which maintains social unity.",
    "seva_10_title": "10. Tribal Cultural Heritage & Faith Preservation",
    "seva_1_desc": "Round-the-clock satvik Mahaprasad served freely to hundreds of thousands of pilgrims during the 4-day Mahashivratri festival.",
    "seva_1_detail": "In accordance with the sacred maxim 'Annam Brahm' (Food is God), thousands of devotees are served Mahaprasad during the auspicious festival of Mahashivratri. The primary objective of this service is not merely to satiate hunger, but to circulate equality, brotherhood, and sattvic energy among devotees through the medium of Prasad. This initiative brings people from all strata of society together to sit in a single row (Panghat), receiving divine blessings as one.",
    "seva_1_title": "1. Mahashivratri 4-Day Annapurna Prasad",
    "seva_2_desc": "Sanctuary and medical care for indigenous Dangi and Gir cows, providing organic green fodder and lifelong protection.",
    "seva_2_detail": "The Dham is deeply committed to protecting the Gomata (Mother Cow), who is considered the backbone of Indian culture. We provide a safe haven for cows that are sick, elderly, or abandoned, ensuring they receive high-quality fodder and necessary medical treatment. This initiative is more than just service; it is a dedicated effort to sustain the cycle of nature, which helps in environmental conservation and brings spiritual prosperity to all.",
    "seva_2_title": "2. Surabhi Goshala & Cow Protection",
    "seva_3_desc": "Preservation and planting of indigenous Teak, Banyan, Peepal, and rare medicinal herbs across the sacred Dang forest.",
    "seva_3_detail": "Based on the philosophy that \"Nature is the true Manifestation of God,\" large-scale plantation drives are conducted under the 'Vasundhara' initiative. The core of this mission is not just to plant trees, but to nurture them to maturity, ensuring ecological balance. By doing so, we aim to control pollution and gift the coming generations a legacy of pure air and a lush, green Earth.",
    "seva_3_title": "3. Vasundhara Nature & Forest Afforestation",
    "seva_4_desc": "Free education, traditional Vedic values, yogic discipline, and livelihood training for tribal children of Dang.",
    "seva_4_detail": "To ensure that our foundational culture is not lost in the flow of modern education, the 'Gurukul' system is used to instill Vedic values and disciplined samskaras in students. Here, the emphasis is placed on character building alongside knowledge acquisition. Our goal is to shape a future society that is intellectually profound, well-educated, and takes pride in its righteous heritage.",
    "seva_4_title": "4. Tribal Gurukul & Vedic Education",
    "seva_5_desc": "Grassroots de-addiction counseling camps, family rehabilitation, and health awareness across rural forest settlements.",
    "seva_5_detail": "To rescue families devastated by the grip of addiction, the Dham provides specialized counseling and spiritual interventions. This initiative focuses on dissuading the youth from alcohol and other harmful substances, guiding them toward a righteous and purposeful life. The success of this campaign lies in its ability to restore social health and empower families to live happy, stable lives once again.",
    "seva_5_title": "5. Alcohol De-Addiction & Social Upliftment",
    "seva_6_desc": "Traditional Vedic rites for spatial sanctification, home purification, and agricultural prosperity according to scripture.",
    "seva_6_detail": "To ensure the flow of positive energy within homes and workplaces, Vastu Pujan is performed according to authentic Vedic scriptures. By harmonizing the living space with the Panchamahabhutas (the five core elements of nature), this ritual aims to eliminate negativity and invite peace, happiness, and prosperity into the environment.",
    "seva_6_title": "6. Traditional Vastu Poojan & Sanctification",
    "seva_7_desc": "Restoration of ancient neglected stone shrines across the Sahyadri ranges with authentic Vedic consecration rituals.",
    "seva_7_detail": "One of the Dham's vital missions is the restoration of ancient, neglected temples and the ceremonial installation of new deities (Pran-Pratishtha). Reviving these sacred spaces rejuvenates the spiritual atmosphere of the community and provides a holy center where society can gather in unity and devotion.",
    "seva_7_title": "7. Shrines Restoration & Consecration Ceremony",
    "seva_8_desc": "Dedicated assistance, mobility equipment, and healthcare relief for differently-abled and ailing devotees.",
    "seva_8_detail": "Seeing 'Narayan' (the Divine) in the helpless and those suffering from physical ailments, the Dham is dedicated to their service. The goal is to make the needy self-reliant by providing wheelchairs and essential medical treatments. This support instills a renewed hope for life among the most vulnerable sections of society.",
    "seva_8_title": "8. Seva for Differently-Abled & Medically Ailing",
    "seva_9_desc": "Community spiritual awakening through saintly discourses, devotional sankirtan, and sacred Vedic traditions.",
    "seva_9_detail": "Various lectures and workshops are organized to reach people with the great traditions, scriptures, and scientific reasons behind festivals in Hindu Dharma. This awakening removes misconceptions in society and creates a sense of justified pride and self-confidence in everyone about their glorious culture.",
    "seva_9_title": "9. Sanatan Hindu Dharma Awakening Mission",
    "seva_annakshetra_desc": "Daily pure satvik mahaprasad served freely to all pilgrims, forest tribes, and sadhus.",
    "seva_annakshetra_title": "Annakshetra Mahaprasad",
    "seva_badge_1": "SEVA 01",
