    "seva_forest_desc": "Preservation of ancient sacred teaks, banyans, and medicinal flora in the Dang hills.",
    "seva_forest_title": "Forest Sanctuary Afforestation",
    "seva_goshala_desc": "Dedicated shelter and medicinal care for indigenous Dangi and Gir cows.",
    "seva_goshala_title": "Surabhi Goshala Seva",
