    "swamiji_badge": "૪૦+ વર્ષ વન તપસ્યા",
    "swamiji_btn": "Read Swamiji's Sacred Chronicle →",
    "swamiji_card1_desc": "ડાંગના ગાઢ અરણ્યમાં એકાંતવાસ ભોગવી જંગલનાં પાંદડાં, ફૂલો અને પાણી ગ્રહણ કરી એક વર્ષ, ત્રણ મહિના અને બાર દિવસ ઘોર તપસ્યા કરી.",
    "swamiji_card1_title": "અખંડ મૌન અને કઠોર તપસ્યા",
    "swamiji_card2_desc": "ભગવાન શિવ અને માતા પાર્વતીના સાક્ષાત્કારથી સ્વામીજીને ચાર વેદોનું જ્ઞાન અને યોગ દ્વારા ૮૧ વિદ્યાઓનું જ્ઞાન પ્રાપ્ત થયું.",
    "swamiji_card2_title": "વેદ જ્ઞાન અને ૮૧ વિદ્યાઓ",
    "swamiji_card3_desc": "દારૂ અને તમાકુના વ્યસનમાંથી હજારો લોકોને મુક્ત કરી દીર્ઘકાલીન દર્દીઓને નિઃશુલ્ક આધ્યાત્મિક અને ઔષધીય માર્ગદર્શન આપ્યું.",
    "swamiji_card3_title": "નિઃશુલ્ક વ્યસનમુક્તિ અને આરોગ્ય સેવા",
    "swamiji_card4_desc": "સ્વયંભૂ શિવ અર્ધનરેશ્વર, નાગદેવતા, વાઘોબા, રાધાકૃષ્ણ અને પંચમુખી હનુમાનજીની પવિત્ર પ્રાણપ્રતિષ્ઠા કરી ભક્તિમય ધામનું સર્જન કર્યું.",
    "swamiji_card4_title": "બિમલાલ તુલસીગઢ સ્થાપના",
    "swamiji_desc": "Over 40 years of solitary forest meditation, tribal welfare, and the spiritual renaissance of the Ardhanarishwara Jyotirling sanctuary.",
    "swamiji_karya_desc": "Tribal spiritual upliftment, cow protection, Dang forest conservation, substance de-addiction, and Sanatan cultural preservation are the central pillars of Swamiji’s lifelong tapasya.",
    "swamiji_karya_title": "Pujya Swamiji’s Lifelong Mission & Social Seva",
    "swamiji_lead": "ડાંગના પાવન દંડકારણ્યમાં અખંડ શિવ આરાધના, ગોરક્ષા અને આદિવાસી જનકલ્યાણ માટે પોતાનું જીવન સમર્પિત કરનાર સાચા તપસ્વી સંત.",
    "swamiji_name_full": "Mathadhipati Param Pujya Sant Swami Anekarupiji Maharaj",
    "swamiji_parichay_dharma": "Through the Sanatan Hindu Dharma Jagrutam initiative, he tirelessly works to ignite the flame of faith, preserving our heritage and safeguarding the local community against the tides of religious conversion.",
    "swamiji_parichay_heading": "The Divine Mission of P.P. Saint Swami Anekrupi Maharaj",
    "swamiji_parichay_quote": "He attained profound knowledge of the four Vedas and 51 different sciences, which became the foundation for his lifelong mission of social service. Swamiji's abode serves as a major spiritual sanctuary for devotees traveling from Maharashtra, Gujarat, Rajasthan, and Madhya Pradesh.",
    "swamiji_parichay_remedies": "Swamiji offers infallible Vedic remedies for planetary afflictions, including Graha, Nakshatra, and Kaal Sarp Doshas, while leading souls toward Vyasanmukti (freedom from addiction) and mental peace.",
    "swamiji_parichay_restoration": "As the visionary architect of spiritual revival, Swamiji has led the Punarsthapana (Restoration) and Pran-Pratishtha (Consecration) of both ancient and new shrines, restoring the Vedic vibrations of these sacred sites.",
    "swamiji_parichay_rituals": "He oversees grand spiritual events, including Maha Rudra Abhishek, Yagyas, and Satsangs, to purify the atmosphere and uplift the consciousness of all seekers.",
    "swamiji_parichay_seva": "Most remarkably, Swamiji performs this entire divine mission entirely free of charge, dedicated solely to the spiritual liberation and wellbeing of every soul.",
    "swamiji_parichay_tapasya": "Having surrendered to rigorous spiritual penance (Japa-Tapa) since his balyavastha (childhood), Swamiji was graced with divine boons and Siddhis by Lord Shiva and Mother Parvati.",
    "swamiji_quote": "“સેવા એ જ સાધના અને ઈશ્વર ભક્તિ એ જ જીવનનો સાચો ઉદ્ધાર છે.”",
    "swamiji_subtitle": "ડાંગના દંડકારણ્યમાં ૪૦ વર્ષથી અખંડ મૌન તપસ્યા અને લોકસેવા કરનાર સિદ્ધ સંત",
