    "hero_badge": "ડાંગ અરણ્યની સ્વયંભૂ પવિત્ર તપોભૂમિ",
    "hero_btn_chronicle": "સ્વામીજી જીવનગાથા",
    "hero_btn_plan": "દર્શન યાત્રા આયોજન",
    "hero_main_desc_1": "ગુજરાત રાજ્યના ડાંગ જિલ્લાના આહવા તાલુકામાં આવેલા બિલમાલ ગામના તુલસીગઢ પવિત્ર સ્થળે, પૂજ્ય ગુરુ સ્વામી અનેકરૂપી મહારાજના માર્ગદર્શન હેઠળ ભગવાન શિવ અર્ધનરેશ્વરની સ્થાપના કરવામાં આવી છે. પુરાણો અનુસાર, આ વિસ્તાર 'દંડકારણ્ય' ક્ષેત્ર તરીકે ઓળખાતો હતો. અહીં મુખ્યત્વે નાગદેવતા અને વાઘોબા (વાઘદેવ)ની મૂર્તિઓ પણ પ્રતિષ્ઠિત છે. તેની સાથે રાધા-કૃષ્ણ, વિઠ્ઠલ-રુકમિણી, રામ-લક્ષ્મણ-જાનકી, હનુમાનજી, પંચમુખી હનુમાન, ખંડેરાવ મહારાજ અને ભગવાન ગણેશજી પણ બિરાજમાન છે. ભારતમાં એકમાત્ર 'શિવ અર્ધનરેશ્વર નાગ જ્યોતિર્લિંગ ધામ' તુલસીગઢ, બિલમાલ ખાતે જ દર્શન માટે ઉપલબ્ધ છે.",
    "hero_main_desc_2": "આ પવિત્ર ધામમાં આવવાથી મંદિર અને સ્વામીજીના સાન્નિધ્યમાં દૈવી શક્તિની અનુભૂતિ થાય છે. તેમજ અહીં અન્ય અનેક ભક્તોના શ્રદ્ધાપૂર્ણ અને દિવ્ય અનુભવોના દર્શન થાય છે.",
    "hero_presence_tag": "સહ્યાદ્રિ પર્વતમાળામાં પ્રકૃતિરૂપ શિવના સાક્ષાત દર્શન",
    "hero_subtitle": "શ્રી શિવ અર્ધનરેશ્વરી નાગ જ્યોતિર્લિંગ ધામ — ગાઢ વનની પાષાણ ગુફા ગર્ભગૃહ, અખંડ વૈદિક નામઘોષ અને પૂજ્ય સ્વામીજીની ૪૦ વર્ષોની મૌન પ્રકૃતિ તપસ્યા.",
    "hero_threshold_text": "જંગલ જેમ પ્રવેશ કરે છે, તેમ જ શ્રદ્ધાથી પ્રવેશ કરો.",
