    "layout_desc": "બિમલાલ ધામમાં પવિત્ર ગુફા મંદિર, ગૌશાળા, ગુરુકુલ અને પ્રવેશદ્વારની ઇન્ટરેક્ટિવ રૂપરેખા. ચાલવાનું અંતર, સમય અને સુવિધાઓ જોવા માટે પિન પર ક્લિક કરો.",
