    "mandir_info_desc": "ડાંગના ગાઢ દંડકારણ્યમાં સ્વયંભૂ પ્રગટ થયેલ દિવ્ય પાષાણ ગુફા ગર્ભગૃહ અને પૂજ્ય સ્વામીજીની પાવન તપોભૂમિ.",
    "mandir_info_title": "શ્રી શિવ અર્ધનરેશ્વર પાવન પરિચય",
    "mandir_parichay_ancient": "પ્રાચીન દંડકારણ્ય તપોભૂમિ: પ્રભુ શ્રીરામ અને ઋષિમુનિઓની પાવન ચરણરજથી પવિત્ર થયેલો વિસ્તાર.",
    "mandir_parichay_divine": "સ્વયંભૂ નાગદેવતા અને વાઘોબા: અરણ્યની રક્ષા કરતા પ્રાચીન દેવતાઓનું પાવન અધિષ્ઠાન.",
    "mandir_parichay_establishment": "સ્થાપના અને પૃષ્ઠભૂમિ: બિલમાલ તુલસીગઢ ખાતે પૂજ્ય સ્વામીજીના માર્ગદર્શનમાં ભગવાન શિવ અર્ધનરેશ્વરની સ્થાપના કરવામાં આવી.",
    "mandir_parichay_heading": "મંદિર પરિચય અને આધ્યાત્મિક રહસ્ય",
    "mandir_parichay_historical": "ભારતનું અનોખું શિવ અર્ધનરેશ્વર નાગ જ્યોતિર્લિંગ ધામ જનકલ્યાણનું કેન્દ્ર બની રહ્યું છે.",
    "mathadhipati_title": "મઠાધિપતિ: પ.પૂ. સંત સ્વામી અનેકરૂપીજી મહારાજ",
    "nag_dwar_sub": "અરણ્ય રક્ષક પ્રાચીન દૈવી શક્તિઓનું સાન્નિધ્ય",
    "nag_dwar_title": "નાગદ્વાર અને વાઘદેવ પીઠ",
    "nav_contact": "પ્રવાસ અને સંપર્ક",
    "nav_darshan": "દર્શન",
    "nav_events": "ઉત્સવ",
    "nav_gallery": "દર્શન ગેલેરી",
    "nav_home": "મુખ્ય પૃષ્ઠ",
    "nav_niyamavali": "આચારસંહિતા અને નિયમો",
    "nav_seva": "સેવા",
    "nav_swamiji": "સ્વામીજી",
    "nav_temple": "મંદિર પરિચય",
    "nav_trust": "વિશ્વસ્ત મંડળ અને દાન",
    "nav_yatra": "યાત્રા માર્ગ",
    "news_placeholder_desc": "સત્તાવાર વર્તમાનપત્ર અહેવાલો અને ઐતિહાસિક પ્રેસ કટિંગ્સ ટૂંક સમયમાં અહીં પ્રદર્શિત કરવામાં આવશે.",
    "news_placeholder_title": "ટૂંક સમયમાં ઉપલબ્ધ થશે",
    "news_section_tag": "સમાચાર અને પ્રેસ કવરેજ",
    "news_section_title": "પ્રેસ કવરેજ અને વર્તમાનપત્ર સંગ્રહ",
    "niyam_1": "૧. પવિત્રતા અને સ્વચ્છતા: મંદિરમાં પ્રવેશતાં પહેલાં સ્નાન કરી તન-મન શુદ્ધ રાખવું. મંદિર પરિસરમાં થૂંકવું કે કચરો કરવો નિષેધ છે.",
    "niyam_10": "૧૦. નશામુક્તિ અને તંદુરસ્તી: મંદિરમાં ગુટખા, તમાકુ, સિગારેટ કે દારૂ જેવા નશીલા પદાર્થો લાવવા કે સેવન કરવા પર સખત પ્રતિબંધ છે.",
    "niyam_11": "૧૧. વન્યજીવ સાવચેતી: મંદિર પરિસર ગાઢ વનમાં હોવાથી એકલા ન ફરવું અને વન્ય પ્રાણીઓને ખોરાક આપવો નહીં કે પજવવા નહીં. સૂર્યાસ્ત પછી પરિસરમાં બિનજરૂરી ભટકવું ટાળવું.",
    "niyam_2": "૨. પાદુકા/જોડા: મંદિરમાં પ્રવેશતાં પહેલાં પગરખાં (જોડા-ચંપલ) બહાર નિયુક્ત સ્થાન પર જ ઉતારવા.",
    "niyam_3": "૩. વેશભૂષા (Dress Code): ભારતીય સંસ્કૃતિને અનુરૂપ અને મર્યાદિત વસ્ત્રો પહેરવાં. ટૂંકા કે અશોભનીય વસ્ત્રો પહેરી મંદિરમાં પ્રવેશ કરવો નહીં.",
    "niyam_4": "૪. શાંતિ અને શિસ્ત: મંદિર પરિસરમાં મૌન પાળવું. બૂમો પાડવી, મોટેથી બોલવું કે દોડવું ટાળવું. મોબાઇલ ફોન બંધ રાખવો અથવા 'સાયલન્ટ મોડ' પર રાખવો.",
    "niyam_5": "૫. પૂજા અને અર્ચન: ભગવાનના દર્શન શાંતિથી કરવાં. પૂજારીની સૂચના અનુસાર જ પૂજા-અર્ચન કરવી. મૂર્તિઓને અયોગ્ય સ્પર્શ કરવો નહીં.",
    "niyam_6": "૬. ભેટ અને દાન: દાન કે ભેટ માત્ર અધિકૃત દાનપેટીમાં જ નાખવી અથવા કાર્યાલયમાંથી સત્તાવાર રસીદ મેળવવી. અનધિકૃત વ્યક્તિઓને દાન આપવું નહીં.",
    "niyam_7": "૭. મહિલાઓ માટે નિયમ: માસિક ધર્મના સમયગાળા દરમિયાન સ્ત્રીઓએ મંદિરમાં પ્રવેશ કરવો નહીં.",
    "niyam_8": "૮. નાના બાળકોની કાળજી: બાળકો મંદિર પરિસરમાં તોફાન ન કરે કે મૂર્તિઓને અડકે નહીં તેનું ધ્યાન રાખવું.",
    "niyam_9": "૯. સૂતક સમયગાળો: સૂતકના દિવસોમાં (સામાન્ય રીતે ૧૦ થી ૧૩ દિવસ) બહાર કોઈને ત્યાં ભોજન ન કરવું કે ઘરનું અન્ન કોઈને ન આપવું. શુદ્ધિકરણ વિધિ થયા પછી જ મંદિરમાં દર્શને આવવું.",
