    "packing_ctx_desc_monsoon": "ડાંગમાં ૨૫૦૦ મિમીથી વધુ વરસાદ પડે છે. ધોધમાર વરસાદ અને લપસણા ઘાટ રસ્તાઓ માટે વોટરપ્રૂફ તૈયારી આવશ્યક છે.",
    "packing_ctx_desc_summer": "બપોરે તાપમાન ૩૮° સેલ્સિયસ સુધી પહોંચે છે. પૂરતું પાણી અને સુતરાઉ વસ્ત્રો પહેરવાં.",
