    "packing_eco_note": "ડાંગ એક સંરક્ષિત વન્યજીવ અભયારણ્ય છે — કૃપા કરીને પ્લાસ્ટિક કચરો ન ફેંકવો અને પાવન શાંતિ જાળવવી.",
    "packing_item_all_season_1_desc": "દર્શન નોંધણી અને સુરક્ષા ચકાસણી વખતે દર્શાવવા.",
    "packing_item_all_season_1_title": "મૂળ ઓળખપત્ર (આધાર કાર્ડ / ચૂંટણી કાર્ડ)",
