    "packing_item_all_season_3_desc": "જંગલ વિસ્તાર હોવાથી નજીકમાં મેડિકલ સ્ટોર નથી; પોતાની દવાઓ સાથે રાખવી.",
    "packing_item_all_season_3_title": "નિયમિત અંગત દવાઓ અને ફર્સ્ટ એઇડ",
    "packing_item_all_season_4_desc": "જંગલમાં નેટવર્ક ન હોવાથી ઓનલાઇન યુપીઆઈ (UPI) ચાલતું નથી; પૂરતી રોકડ રાખવી.",
    "packing_item_all_season_4_title": "જરૂરી રોકડ રકમ",
    "packing_item_all_season_5_desc": "કોઈપણ કચરો જંગલમાં ન ફેંકતાં પોતાની બેગમાં સાચવી રાખવો.",
    "packing_item_all_season_5_title": "કચરા માટે અલગ ઇકો-બેગ",
    "packing_item_monsoon_1_desc": "ડાંગના પવન સાથે વરસતા વરસાદમાં હલકી છત્રી કામ લાગતી નથી.",
    "packing_item_monsoon_1_title": "મજબૂત છત્રી અથવા પૂર્ણ લંબાઈનો રેઇનકોટ",
    "packing_item_monsoon_2_desc": "ગુફાનાં પથ્થરિયાં પગથિયાં લપસણાં હોવાથી મજબૂત ગ્રીપવાળાં પગરખાં જરૂરી છે.",
    "packing_item_monsoon_2_title": "સારી પકડવાળા રબરનાં પગરખાં / સેન્ડલ",
    "packing_item_monsoon_3_desc": "આકસ્મિક વરસાદથી ઇલેક્ટ્રોનિક ઉપકરણો અને પાસ સાચવવા ઝિપલોક બેગ વાપરો.",
    "packing_item_monsoon_3_title": "મોબાઇલ અને સામાન માટે વોટરપ્રૂફ કવર",
    "packing_item_monsoon_4_desc": "ગર્ભગૃહમાં પલળેલાં કપડે પ્રવેશ કરવો નહીં; સાથે સૂકાં વસ્ત્રો રાખવાં.",
