    "packing_reset_btn": "રીસેટ કરો",
    "packing_subtitle": "ડાંગના જંગલમાં ઋતુ પ્રમાણે વાતાવરણ ઝડપથી બદલાય છે. સહ્યાદ્રિનો મુશળધાર વરસાદ, શિયાળાની રાત કે ઉનાળાની પદયાત્રા — દર્શન સુખદ રહે તે માટે યોગ્ય સામાન સાથે રાખવો.",
