    "parking_rule_1": "૧. કૃપા કરીને પોતાનાં વાહનો નિયુક્ત કરેલ સ્થળે જ અને લાઈનમાં ઊભા રાખવા.",
    "parking_rule_2": "૨. વાહનમાં કિંમતી સામાન કે રોકડ રકમ ન રાખવી; ચોરી થવા પર વ્યવસ્થાપન જવાબદાર રહેશે નહીં.",
    "parking_rule_3": "૩. પાર્કિંગ પરિસર સ્વચ્છ રાખવું.",
    "parking_rule_4": "૪. પરિસરમાં વન્યજીવોની અવરજવર હોઈ શકે છે, તેથી સાવચેત રહેવું અને કોઈ પ્રાણીને હેરાન ન કરવું. વાહન પાર્ક કરી સીધા મંદિરમાં જવું.",
    "parking_rule_5": "૫. સ્વયંસેવકોએ આપેલી સૂચનાઓનું પાલન કરી સહકાર આપવો.",
    "parking_signage": "\"પાર્કિંગ અહીં છે\" (Parking This Way), \"નો પાર્કિંગ\", \"ગતિ મર્યાદા ૫ કિમી\" - સંકેતોનું પાલન કરવું.",
