    "rule_1_desc": "ભારતીય પારંપરિક મર્યાદિત પોશાક પહેરીને જ ગર્ભગૃહમાં પ્રવેશ કરવો.",
    "rule_1_title": "સાત્વિક વસ્ત્રો પરિધાન",
    "rule_2_desc": "ગર્ભગૃહની અંદર ફોટોગ્રાફી કે વીડિયોગ્રાફી સખત મનાઈ છે; ફોન સાયલન્ટ રાખવો.",
