    "seva_btn": "સેવા સહભાગ વિશે જાણો",
    "seva_desc": "મંદિરમાં દરેક સેવા માત્ર દાન નથી, પરંતુ આત્મશુદ્ધિ અને પ્રકૃતિ પૂજનની સાધના છે.",
    "seva_forest_desc": "ડાંગના પાવન અભયારણ્યમાં ઔષધીય વનસ્પતિઓ અને દેશી વૃક્ષોનું સંવર્ધન.",
    "seva_forest_title": "વસુંધરા સંવર્ધન વૃક્ષારોપણ",
    "seva_goshala_desc": "ગીર અને ડાંગી દેશી ગાયોનું સંવર્ધન, પ્રાકૃતિક ઘાસચારો અને બીમાર ગૌવંશની અખંડ સારવાર.",
    "seva_goshala_title": "સુરભી ગૌશાળા અને ગૌરક્ષા",
    "seva_note": "તમામ સેવાઓ નિષ્કામ ભાવે સંચાલિત થાય છે. સેવામાં સહભાગિતા અથવા વધુ માહિતી માટે મંદિર વિશ્વસ્ત કાર્યાલયનો સંપર્ક કરવો.",
    "seva_tag": "નિષ્કામ ભક્તિ અને સેવા",
    "seva_title": "પવિત્ર દસ સેવા",
    "site_full_name": "શ્રી શિવ અર્ધનરેશ્વરી નાગ જ્યોતિર્લિંગ ધામ, બિમલાલ તુલસીગઢ",
    "site_name": "શ્રી શિવ અર્ધનરેશ્વર ધામ",
    "slot_aparahna": "અપરાહ્ન પ્રહર (બપોરે ૦૨:૦૦ - સાંજે ૦૫:૦૦)",
    "slot_madhyahna": "મધ્યાહ્ન મહાપૂજા (સવારે ૧૧:૦૦ - બપોરે ૦૧:૦૦)",
    "slot_sandhya": "સંધ્યા મહાઆરતી (સાંજે ૦૬:૦૦ - રાત્રે ૦૮:૩૦)",
