    "swamiji_awards_desc": "સ્વામીજીની નિષ્કામ અરણ્ય સેવા અને સનાતન ધર્મ જાગૃતિનું વિવિધ સંપ્રદાયો અને સંસ્થાઓ દ્વારા થયેલ સન્માન.",
    "swamiji_awards_title": "સન્માન અને આદર",
    "swamiji_badge": "૪૦+ વર્ષ વન તપસ્યા",
    "swamiji_btn": "સ્વામીજીની જીવનગાથા વાંચો",
    "swamiji_card1_desc": "ડાંગના ગાઢ અરણ્યમાં એકાંતવાસ ભોગવી જંગલનાં પાંદડાં, ફૂલો અને પાણી ગ્રહણ કરી એક વર્ષ, ત્રણ મહિના અને બાર દિવસ ઘોર તપસ્યા કરી.",
    "swamiji_card1_title": "અખંડ મૌન અને કઠોર તપસ્યા",
    "swamiji_card2_desc": "ભગવાન શિવ અને માતા પાર્વતીના સાક્ષાત્કારથી સ્વામીજીને ચાર વેદોનું જ્ઞાન અને યોગ દ્વારા ૮૧ વિદ્યાઓનું જ્ઞાન પ્રાપ્ત થયું.",
    "swamiji_card2_title": "વેદ જ્ઞાન અને ૮૧ વિદ્યાઓ",
    "swamiji_card3_desc": "દારૂ અને તમાકુના વ્યસનમાંથી હજારો લોકોને મુક્ત કરી દીર્ઘકાલીન દર્દીઓને નિઃશુલ્ક આધ્યાત્મિક અને ઔષધીય માર્ગદર્શન આપ્યું.",
    "swamiji_card3_title": "નિઃશુલ્ક વ્યસનમુક્તિ અને આરોગ્ય સેવા",
    "swamiji_card4_desc": "સ્વયંભૂ શિવ અર્ધનરેશ્વર, નાગદેવતા, વાઘોબા, રાધાકૃષ્ણ અને પંચમુખી હનુમાનજીની પવિત્ર પ્રાણપ્રતિષ્ઠા કરી ભક્તિમય ધામનું સર્જન કર્યું.",
    "swamiji_card4_title": "બિમલાલ તુલસીગઢ સ્થાપના",
    "swamiji_desc": "પૂજ્ય સ્વામીજીએ બાલ્યકાળથી જ શિવ ઉપાસના અને જંગલ સાધના દ્વારા દિવ્ય જ્ઞાન પ્રાપ્ત કર્યું. તેઓ નિઃશુલ્ક વ્યસનમુક્તિ, આયુર્વેદિક ઉપચાર અને લોકકલ્યાણકારી માર્ગદર્શન આપી રહ્યા છે.",
    "swamiji_karya_desc": "નિઃશુલ્ક વ્યસનમુક્તિ, આયુર્વેદિક ચિકિત્સા, અન્નદાન અને ભારતીય સંસ્કૃતિ સંરક્ષણ.",
    "swamiji_karya_title": "પૂજ્ય સ્વામીજીનું લોકકલ્યાણ કાર્ય",
    "swamiji_lead": "ડાંગના પાવન દંડકારણ્યમાં અખંડ શિવ આરાધના, ગોરક્ષા અને આદિવાસી જનકલ્યાણ માટે પોતાનું જીવન સમર્પિત કરનાર સાચા તપસ્વી સંત.",
    "swamiji_name_full": "પરમ પૂજ્ય સંત સ્વામી અનેકરૂપીજી મહારાજ",
    "swamiji_parichay_dharma": "જપ અને અનુષ્ઠાનનું મહત્વ: ગુરુના માર્ગદર્શન હેઠળ મંત્રજપ કરવાથી ભગવંત સાધકની મનોકામના પૂર્ણ કરે છે.",
    "swamiji_parichay_heading": "પૂજ્ય સ્વામીજીનું જીવનકાર્ય અને વિચાર",
    "swamiji_parichay_quote": "મકારો મનનં પ્રાહ દકારસ્ત્રાણમુચ્યતે। મનન+ત્રાણસંયુક્તો મંત્રઇત્યભિધીયતે॥",
    "swamiji_parichay_remedies": "ગુરુપૂર્ણિમા મહોત્સવ: શિષ્ય પરિવાર દ્વારા બ્રાહ્મણોના મંત્રોચ્ચાર સાથે પૂજ્ય સ્વામીજીનું ષોડશોપચાર પૂજન કરવામાં આવે છે.",
    "swamiji_parichay_restoration": "સ્વામીજીએ ભક્તોની સમસ્યાઓનું નિવારણ કરી તેમના જીવનને સુખી-સમૃદ્ધ બનાવ્યું. વ્યસનાધીન થયેલા હજારો લોકોને વ્યસનમુક્ત કરી સુસંસ્કૃત બનાવ્યા. આ સેવા સ્વામીજી સંપૂર્ણપણે નિઃશુલ્ક કરે છે.",
    "swamiji_parichay_rituals": "ગુરુ એટલે 'માર્ગદર્શક' અને પૂર્ણિમા એટલે પ્રકાશ. ગુરુ પાસેથી મળેલા જ્ઞાનથી જીવન ઉજ્જવળ બને છે.",
    "swamiji_parichay_seva": "નિષ્કામ લોકસેવા અને આધ્યાત્મિક માર્ગદર્શન એ જ સ્વામીજીના જીવનનો મુખ્ય ઉદ્દેશ છે.",
    "swamiji_parichay_tapasya": "પૂજ્ય સંત સ્વામી અનેકરૂપી મહારાજનો જન્મ ગુજરાત અને મહારાષ્ટ્રની સરહદે આવેલા ડાંગ જિલ્લાના આહવા તાલુકાના બિલમાલ ગામે થયો. બાલ્યકાળમાં જ તેમને ભગવાન શિવ અને માતા પાર્વતીના દર્શન થયા. તેમણે જંગલમાં કઠોર તપસ્યા કરી દિવ્ય સિદ્ધિઓ પ્રાપ્ત કરી.",
    "swamiji_quote": "“સેવા એ જ સાધના અને ઈશ્વર ભક્તિ એ જ જીવનનો સાચો ઉદ્ધાર છે.”",
    "swamiji_subtitle": "ડાંગના દંડકારણ્યમાં ૪૦ વર્ષથી અખંડ મૌન તપસ્યા અને લોકસેવા કરનાર સિદ્ધ સંત",
